// Generated by vibelang from src/device/home-history.ts; the migrate flow writes it again with each batch.
import { Schema } from "effect";
// Frozen home schemas before 3fc7fba8332d (decision 0021). Never import live feature schemas here.
const maximumTitleLength = 120;
const maximumTextLength = 4096;
const maximumUrlLength = 2048;
const maximumEntries = 12;
const maximumStats = 6;
const maximumActions = 3;
const maximumLineLength = 280;
const maximumCodeLength = 4096;
const htmlPattern = /<\/?[A-Za-z!?]/;
const noHtml = Schema.makeFilter((text) => htmlPattern.test(text) ? "must not contain HTML; blocks are declared values, never markup" : true);
const Title = Schema.NonEmptyString.check(Schema.isMaxLength(maximumTitleLength), Schema.isPattern(/^[^\r\n]*$/), noHtml);
const Prose = Schema.NonEmptyString.check(Schema.isMaxLength(maximumTextLength), noHtml);
const Url = Schema.NonEmptyString.check(Schema.isMaxLength(maximumUrlLength), Schema.isPattern(/^https?:\/\/[^\s<>"']+$/i));
const RepositoryPath = Schema.NonEmptyString.check(Schema.isMaxLength(1024), Schema.makeFilter((value) => value.startsWith("/") || value.includes("\\") ||
    value.split("/").some((part) => part === "" || part === "." || part === "..") ||
    /[%:?#]/.test(value) || [...value].some((character) => character.charCodeAt(0) < 0x20)
    ? "must be a relative in-repository path" :
    true));
const FlowName = Schema.NonEmptyString.check(Schema.isPattern(/^[a-z0-9_-]+(?:[./][a-z0-9_-]+)*$/));
const Line = Schema.NonEmptyString.check(Schema.isMaxLength(maximumLineLength), Schema.isPattern(/^[^\r\n]*$/), noHtml);
const Command = Line;
const Code = Schema.NonEmptyString.check(Schema.isMaxLength(maximumCodeLength), Schema.isPattern(/^[^\u0000]*$/));
const Language = Schema.NonEmptyString.check(Schema.isPattern(/^[a-z][a-z0-9+#-]{0,19}$/));
const IsoDate = Schema.String.check(Schema.makeFilter((value) => {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    if (match === null)
        return "must be a date, YYYY-MM-DD";
    const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])];
    const date = new Date(0);
    date.setUTCFullYear(year, month - 1, day);
    return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day
        ? true
        : "must be a date that exists";
}));
const Link = Schema.Struct({ label: Title, url: Url });
const Audience = Schema.Literals(["everyone", "contributor", "maintainer"]);
const Contributors = Schema.Literals(["role", "anyone"]);
const TextBlock = Schema.Struct({
    type: Schema.Literal("text"),
    title: Schema.optional(Title),
    text: Prose
});
const LinksBlock = Schema.Struct({
    type: Schema.Literal("links"),
    title: Schema.optional(Title),
    links: Schema.NonEmptyArray(Link)
});
const FlowsBlock = Schema.Struct({
    type: Schema.Literal("flows"),
    title: Schema.optional(Title)
});
const PromptBlock = Schema.Struct({
    type: Schema.Literal("prompt"),
    flow: Schema.optional(FlowName),
    title: Schema.optional(Title),
    placeholder: Schema.optional(Title)
});
const AppPicture = Schema.Literals(["issue", "review", "wiki", "schedule"]);
const AppBlock = Schema.Struct({
    type: Schema.Literal("app"),
    flow: FlowName,
    title: Title,
    picture: AppPicture
});
const MarkdownBlock = Schema.Struct({
    type: Schema.Literal("markdown"),
    path: RepositoryPath,
    title: Schema.optional(Title)
});
const StackBlock = Schema.Struct({
    type: Schema.Literal("stack"),
    title: Schema.optional(Title)
});
const ViewBlock = Schema.Struct({
    type: Schema.Literal("view"),
    flow: FlowName
});
const HeroBlock = Schema.Struct({
    type: Schema.Literal("hero"),
    title: Title,
    tagline: Schema.optional(Line),
    text: Schema.optional(Line),
    install: Schema.optional(Command),
    actions: Schema.optional(Schema.NonEmptyArray(Link).check(Schema.isMaxLength(maximumActions))),
    announcement: Schema.optional(Link)
});
const CodeBlock = Schema.Struct({
    type: Schema.Literal("code"),
    title: Schema.optional(Title),
    file: Schema.optional(Title),
    language: Schema.optional(Language),
    code: Code
});
const Card = Schema.Struct({
    title: Title,
    text: Schema.optional(Line),
    label: Schema.optional(Title),
    url: Schema.optional(Url)
});
const CardsBlock = Schema.Struct({
    type: Schema.Literal("cards"),
    title: Schema.optional(Title),
    cards: Schema.NonEmptyArray(Card).check(Schema.isMaxLength(maximumEntries)),
    more: Schema.optional(Link)
});
const Stat = Schema.Struct({ value: Title, label: Title });
const StatsBlock = Schema.Struct({
    type: Schema.Literal("stats"),
    title: Schema.optional(Title),
    stats: Schema.NonEmptyArray(Stat).check(Schema.isMaxLength(maximumStats))
});
const Release = Schema.Struct({
    name: Title,
    url: Url,
    date: IsoDate,
    summary: Schema.optional(Line)
});
const ReleasesBlock = Schema.Struct({
    type: Schema.Literal("releases"),
    title: Schema.optional(Title),
    releases: Schema.NonEmptyArray(Release).check(Schema.isMaxLength(maximumEntries)),
    more: Schema.optional(Link)
});
const IssuesBlock = Schema.Struct({
    type: Schema.Literal("issues"),
    title: Schema.optional(Title)
});
const Key = Schema.String.check(Schema.isPattern(/^[a-z]$/));
const ActionBlock = Schema.Struct({
    type: Schema.Literal("action"),
    flow: FlowName,
    title: Title,
    key: Schema.optional(Key)
});
const RunsBlock = Schema.Struct({
    type: Schema.Literal("runs"),
    title: Schema.optional(Title)
});
const Block = Schema.Union([
    TextBlock,
    LinksBlock,
    FlowsBlock,
    PromptBlock,
    MarkdownBlock,
    StackBlock,
    AppBlock,
    ViewBlock,
    HeroBlock,
    CodeBlock,
    CardsBlock,
    StatsBlock,
    ReleasesBlock,
    IssuesBlock,
    RunsBlock,
    ActionBlock
]);
const Section = Schema.Struct({
    title: Schema.optionalKey(Schema.String),
    audience: Audience,
    blocks: Schema.Array(Block),
});
/** homes v2, before 3fc7fba8332d bounded flow names and link lists. */
export const HomeRowV2 = Schema.Struct({
    key: Schema.String,
    state: Schema.Literals(["declared", "absent", "invalid", "unreadable"]),
    sections: Schema.Array(Section),
    contributors: Contributors,
    skipped: Schema.Number,
    reason: Schema.NullOr(Schema.String),
});
/** curated-homes v1, before the same bounds. */
export const CuratedRowV1 = Schema.Struct({
    key: Schema.String,
    state: Schema.Literals(["declared", "absent"]),
    defaultBranch: Schema.NullOr(Schema.String),
    sections: Schema.Array(Section),
});
